"""Small helpers: date parsing and money rounding."""

import datetime
from typing import Union

from dateutil import parser as _du_parser

Dateish = Union[str, datetime.date]


def parse_date(text):
    """Parse a date string in a variety of formats, returning a date object.

    A bare YYYY-MM is treated as the first day of that month. All other
    formats are delegated to python-dateutil, which understands ISO 8601,
    US/EU orderings, natural language ("March 4th", "4 Mar 2024"), and more.
    Raises ValueError on unrecognisable input.
    """
    text = text.strip()
    # Intercept YYYY-MM before dateutil sees it: dateutil would fill in
    # today's day rather than day=1.
    try:
        return datetime.datetime.strptime(text, "%Y-%m").date()
    except ValueError:
        pass
    try:
        return _du_parser.parse(text).date()
    except (ValueError, OverflowError) as exc:
        raise ValueError("unrecognized date {!r}".format(text)) from exc

